select *, sum(units) over (partition by store_id order by revenue, id rows between 3 preceding and current row) as last4_sum_units, avg(units) over (partition by store_id order by revenue, id rows between 3 preceding and current row) as last4_avg_units, count(units) over (partition by store_id order by revenue, id rows between 3 preceding and current row) as last4_count_units, max(units) over (partition by store_id order by revenue, id rows between 3 preceding and current row) as last4_max_units from store_sales
